-- Frozen synthetic T-017 schema14 state captured through its release API.
-- Install rows in one deferred-FK transaction; preserve original journal bytes.
CREATE TABLE materials (
                id TEXT PRIMARY KEY NOT NULL,
                name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 100),
                unit TEXT NOT NULL CHECK(length(unit) BETWEEN 1 AND 20),
                created_at TEXT NOT NULL
            );
CREATE TABLE snapshot_outbox (
                sequence INTEGER PRIMARY KEY AUTOINCREMENT,
                payload TEXT NOT NULL,
                published INTEGER NOT NULL DEFAULT 0 CHECK(published IN (0, 1))
            );
CREATE TABLE creation_requests (
                request_id TEXT PRIMARY KEY NOT NULL,
                name TEXT NOT NULL,
                unit TEXT NOT NULL,
                material_id TEXT NOT NULL UNIQUE REFERENCES materials(id)
            );
CREATE TABLE material_versions(
        id TEXT PRIMARY KEY NOT NULL,material_id TEXT NOT NULL REFERENCES materials(id),name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 100),unit TEXT NOT NULL CHECK(length(unit) BETWEEN 1 AND 20),canonical_unit TEXT NOT NULL,dimension TEXT NOT NULL CHECK(dimension IN('mass','volume','custom')),kind TEXT NOT NULL CHECK(kind IN('raw','prepared','stocked','menu','unclassified')),description TEXT NOT NULL,archived INTEGER NOT NULL CHECK(archived IN(0,1)),recorded_at TEXT NOT NULL,sequence INTEGER REFERENCES snapshot_outbox(sequence),source TEXT NOT NULL,UNIQUE(material_id,id));
CREATE TABLE material_heads(material_id TEXT PRIMARY KEY NOT NULL REFERENCES materials(id),current_version_id TEXT NOT NULL,FOREIGN KEY(material_id,current_version_id) REFERENCES material_versions(material_id,id));
CREATE TABLE material_prices(id TEXT PRIMARY KEY NOT NULL,material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,quantity_micros INTEGER NOT NULL CHECK(quantity_micros>0 AND quantity_micros<=9000000000000000),amount_micros INTEGER NOT NULL CHECK(amount_micros>=0 AND amount_micros<=9000000000000000000),unit TEXT NOT NULL,input_quantity TEXT NOT NULL,input_unit TEXT NOT NULL,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id));
CREATE TABLE mutation_requests(request_id TEXT PRIMARY KEY NOT NULL,operation TEXT NOT NULL,payload TEXT NOT NULL,response TEXT NOT NULL,epoch TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence));
CREATE TABLE catalog_state(singleton INTEGER PRIMARY KEY CHECK(singleton=1),epoch TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>=0));
CREATE TABLE business_records(
            id TEXT PRIMARY KEY NOT NULL,kind TEXT NOT NULL,
            created_at TEXT NOT NULL,created_sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),
            corrects_confirmation_id TEXT REFERENCES business_confirmations(id));
CREATE TABLE business_revisions(
            id TEXT PRIMARY KEY NOT NULL,record_id TEXT NOT NULL REFERENCES business_records(id),
            previous_revision_id TEXT,status TEXT NOT NULL CHECK(status IN('draft','confirmed','archived')),
            payload_version INTEGER NOT NULL CHECK(payload_version=1),payload_json TEXT NOT NULL,
            recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),
            UNIQUE(record_id,id),FOREIGN KEY(record_id,previous_revision_id) REFERENCES business_revisions(record_id,id));
CREATE TABLE business_heads(
            record_id TEXT PRIMARY KEY NOT NULL REFERENCES business_records(id),current_revision_id TEXT NOT NULL,
            FOREIGN KEY(record_id,current_revision_id) REFERENCES business_revisions(record_id,id));
CREATE TABLE business_confirmations(
            id TEXT PRIMARY KEY NOT NULL,record_id TEXT NOT NULL UNIQUE REFERENCES business_records(id),
            revision_id TEXT NOT NULL UNIQUE,request_id TEXT NOT NULL UNIQUE REFERENCES mutation_requests(request_id) DEFERRABLE INITIALLY DEFERRED,
            recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),
            FOREIGN KEY(record_id,revision_id) REFERENCES business_revisions(record_id,id));
CREATE TABLE business_catalog_price_results(
            confirmation_id TEXT PRIMARY KEY NOT NULL REFERENCES business_confirmations(id),
            price_id TEXT NOT NULL UNIQUE REFERENCES material_prices(id));
CREATE TABLE business_corrections(
            target_confirmation_id TEXT PRIMARY KEY NOT NULL REFERENCES business_confirmations(id),
            replacement_confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),
            CHECK(target_confirmation_id<>replacement_confirmation_id));
CREATE TABLE purchase_orders(id TEXT PRIMARY KEY NOT NULL,first_confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),created_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence));
CREATE TABLE recipe_versions(id TEXT PRIMARY KEY NOT NULL,material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,previous_version_id TEXT,copied_from_version_id TEXT REFERENCES recipe_versions(id),basis_count INTEGER NOT NULL CHECK(basis_count BETWEEN 1 AND 1000000000),reference_quantity_micros INTEGER CHECK(reference_quantity_micros>0 AND reference_quantity_micros<=9000000000000000),reference_unit TEXT,reference_input_quantity TEXT,reference_input_unit TEXT,selling_price_micros INTEGER CHECK(selling_price_micros>=0 AND selling_price_micros<=9000000000000000000),cooking_description TEXT NOT NULL,process TEXT NOT NULL,reference_time TEXT NOT NULL,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),UNIQUE(material_id,id),FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id),FOREIGN KEY(material_id,previous_version_id) REFERENCES recipe_versions(material_id,id),CHECK((reference_quantity_micros IS NULL AND reference_unit IS NULL AND reference_input_quantity IS NULL AND reference_input_unit IS NULL) OR (reference_quantity_micros IS NOT NULL AND reference_unit IS NOT NULL AND reference_input_quantity IS NOT NULL AND reference_input_unit IS NOT NULL AND basis_count=1)),CHECK(previous_version_id IS NULL OR copied_from_version_id IS NULL));
CREATE TABLE recipe_lines(id TEXT PRIMARY KEY NOT NULL,recipe_version_id TEXT NOT NULL REFERENCES recipe_versions(id),position INTEGER NOT NULL CHECK(position>=0),material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,quantity_micros INTEGER NOT NULL CHECK(quantity_micros>=0 AND quantity_micros<=9000000000000000),unit TEXT NOT NULL,input_quantity TEXT NOT NULL,input_unit TEXT NOT NULL,note TEXT NOT NULL,UNIQUE(recipe_version_id,position),FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id));
CREATE TABLE recipe_heads(material_id TEXT PRIMARY KEY NOT NULL REFERENCES materials(id),current_version_id TEXT NOT NULL,FOREIGN KEY(material_id,current_version_id) REFERENCES recipe_versions(material_id,id));
CREATE TABLE productions(
            id TEXT PRIMARY KEY NOT NULL,
            confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),
            note TEXT NOT NULL,
            total_input_value_micros INTEGER NOT NULL CHECK(total_input_value_micros>=0 AND total_input_value_micros<=9000000000000000000),
            recorded_at TEXT NOT NULL,
            sequence INTEGER NOT NULL UNIQUE REFERENCES snapshot_outbox(sequence));
CREATE TABLE production_effects(
            id TEXT PRIMARY KEY NOT NULL,
            production_id TEXT NOT NULL REFERENCES productions(id),
            material_id TEXT NOT NULL,
            material_version_id TEXT NOT NULL,
            input_quantity_micros INTEGER NOT NULL CHECK(input_quantity_micros>=0 AND input_quantity_micros<=9000000000000000),
            input_value_micros INTEGER NOT NULL CHECK(input_value_micros>=0 AND input_value_micros<=9000000000000000000),
            output_quantity_micros INTEGER NOT NULL CHECK(output_quantity_micros>=0 AND output_quantity_micros<=9000000000000000),
            output_value_micros INTEGER NOT NULL CHECK(output_value_micros>=0 AND output_value_micros<=9000000000000000000),
            UNIQUE(production_id,material_id),
            UNIQUE(material_id,id),
            UNIQUE(production_id,material_id,material_version_id,id),
            FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id),
            CHECK(input_quantity_micros>0 OR output_quantity_micros>0),
            CHECK(input_quantity_micros>0 OR input_value_micros=0),
            CHECK(output_quantity_micros>0 OR output_value_micros=0));
CREATE TABLE production_inputs(
            production_id TEXT NOT NULL REFERENCES productions(id),
            position INTEGER NOT NULL CHECK(position>=0 AND position<100),
            effect_id TEXT NOT NULL,
            material_id TEXT NOT NULL,
            material_version_id TEXT NOT NULL,
            quantity_micros INTEGER NOT NULL CHECK(quantity_micros>0 AND quantity_micros<=9000000000000000),
            unit TEXT NOT NULL,input_quantity TEXT NOT NULL,input_unit TEXT NOT NULL,
            value_micros INTEGER NOT NULL CHECK(value_micros>=0 AND value_micros<=9000000000000000000),
            PRIMARY KEY(production_id,position),
            FOREIGN KEY(production_id,material_id,material_version_id,effect_id) REFERENCES production_effects(production_id,material_id,material_version_id,id));
CREATE TABLE production_outputs(
            production_id TEXT NOT NULL REFERENCES productions(id),
            position INTEGER NOT NULL CHECK(position>=0 AND position<100),
            effect_id TEXT NOT NULL,
            material_id TEXT NOT NULL,
            material_version_id TEXT NOT NULL,
            quantity_micros INTEGER NOT NULL CHECK(quantity_micros>0 AND quantity_micros<=9000000000000000),
            unit TEXT NOT NULL,input_quantity TEXT NOT NULL,input_unit TEXT NOT NULL,
            value_micros INTEGER NOT NULL CHECK(value_micros>=0 AND value_micros<=9000000000000000000),
            allocation_micros INTEGER NOT NULL CHECK(allocation_micros>=0 AND allocation_micros<=100000000),
            PRIMARY KEY(production_id,position),
            FOREIGN KEY(production_id,material_id,material_version_id,effect_id) REFERENCES production_effects(production_id,material_id,material_version_id,id));
CREATE TABLE sales(
        id TEXT PRIMARY KEY NOT NULL,original_confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),
        material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,recipe_version_id TEXT NOT NULL,
        basis_count INTEGER NOT NULL CHECK(basis_count>0 AND basis_count<=1000000000),
        selling_price_micros INTEGER CHECK(selling_price_micros>=0 AND selling_price_micros<=9000000000000000000),
        known_subtotal_micros INTEGER NOT NULL CHECK(known_subtotal_micros>=0 AND known_subtotal_micros<=9000000000000000000),
        total_cost_micros INTEGER CHECK(total_cost_micros>=0 AND total_cost_micros<=9000000000000000000),
        ratio_json TEXT NOT NULL,ratio_reason_json TEXT NOT NULL,
        FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id),
        FOREIGN KEY(material_id,recipe_version_id) REFERENCES recipe_versions(material_id,id));
CREATE TABLE sale_versions(
        id TEXT PRIMARY KEY NOT NULL,sale_id TEXT NOT NULL REFERENCES sales(id),previous_version_id TEXT,
        confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),count INTEGER NOT NULL CHECK(count>=0 AND count<=1000000000),
        amount_micros INTEGER CHECK(amount_micros>=0 AND amount_micros<=9000000000000000000),note TEXT NOT NULL,
        UNIQUE(sale_id,id),FOREIGN KEY(sale_id,previous_version_id) REFERENCES sale_versions(sale_id,id));
CREATE TABLE sale_heads(
        sale_id TEXT PRIMARY KEY NOT NULL REFERENCES sales(id),current_version_id TEXT NOT NULL,
        FOREIGN KEY(sale_id,current_version_id) REFERENCES sale_versions(sale_id,id));
CREATE TABLE stocktake_batches(id TEXT PRIMARY KEY NOT NULL,confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),note TEXT NOT NULL,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL UNIQUE REFERENCES snapshot_outbox(sequence));
CREATE TABLE stocktake_observations(id TEXT PRIMARY KEY NOT NULL,stocktake_id TEXT NOT NULL REFERENCES stocktake_batches(id),position INTEGER NOT NULL CHECK(position>=0 AND position<100),material_id TEXT NOT NULL REFERENCES materials(id),UNIQUE(stocktake_id,position),UNIQUE(stocktake_id,material_id));
CREATE TABLE correction_records(id TEXT PRIMARY KEY NOT NULL,original_id TEXT NOT NULL,target_confirmation_id TEXT NOT NULL REFERENCES business_confirmations(id),previous_version_id TEXT REFERENCES correction_records(id),confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),business_record_id TEXT NOT NULL REFERENCES business_records(id),recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL UNIQUE REFERENCES snapshot_outbox(sequence),record_json TEXT NOT NULL);
CREATE TABLE correction_event_versions(id TEXT PRIMARY KEY NOT NULL,correction_id TEXT NOT NULL REFERENCES correction_records(id),kind TEXT NOT NULL,original_id TEXT NOT NULL,original_confirmation_id TEXT NOT NULL REFERENCES business_confirmations(id),previous_version_id TEXT,previous_original_version_id TEXT,logical_sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),logical_position INTEGER NOT NULL CHECK(logical_position>=0),recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),row_json TEXT NOT NULL,UNIQUE(kind,original_id,id),UNIQUE(correction_id,kind,original_id),FOREIGN KEY(kind,original_id,previous_version_id) REFERENCES correction_event_versions(kind,original_id,id),CHECK((previous_version_id IS NOT NULL)+(previous_original_version_id IS NOT NULL)=1));
CREATE TABLE correction_event_heads(kind TEXT NOT NULL,original_id TEXT NOT NULL,current_version_id TEXT NOT NULL,PRIMARY KEY(kind,original_id),FOREIGN KEY(kind,original_id,current_version_id) REFERENCES correction_event_versions(kind,original_id,id));
CREATE TABLE correction_projection_versions(id TEXT PRIMARY KEY NOT NULL,correction_id TEXT NOT NULL REFERENCES correction_records(id),kind TEXT NOT NULL,subject_id TEXT NOT NULL,previous_version_id TEXT,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),row_json TEXT NOT NULL,UNIQUE(kind,subject_id,id),UNIQUE(correction_id,kind,subject_id),FOREIGN KEY(kind,subject_id,previous_version_id) REFERENCES correction_projection_versions(kind,subject_id,id));
CREATE TABLE correction_projection_heads(kind TEXT NOT NULL,subject_id TEXT NOT NULL,current_version_id TEXT NOT NULL,PRIMARY KEY(kind,subject_id),FOREIGN KEY(kind,subject_id,current_version_id) REFERENCES correction_projection_versions(kind,subject_id,id));
CREATE TABLE correction_price_bases(id TEXT PRIMARY KEY NOT NULL,correction_id TEXT NOT NULL REFERENCES correction_records(id),material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,amount_micros INTEGER NOT NULL CHECK(amount_micros>=0 AND amount_micros<=9000000000000000000),quantity_micros INTEGER NOT NULL CHECK(quantity_micros>0 AND quantity_micros<=9000000000000000),logical_sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),row_json TEXT NOT NULL,UNIQUE(material_id,id),FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id));
CREATE TABLE "purchase_order_versions"(id TEXT PRIMARY KEY NOT NULL,order_id TEXT NOT NULL REFERENCES purchase_orders(id),previous_version_id TEXT,confirmation_id TEXT NOT NULL REFERENCES business_confirmations(id),action TEXT NOT NULL,status TEXT NOT NULL,material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,quantity_micros INTEGER NOT NULL CHECK(quantity_micros>0 AND quantity_micros<=9000000000000000),unit TEXT NOT NULL,input_quantity TEXT NOT NULL,input_unit TEXT NOT NULL,supplier TEXT,expected_date TEXT,estimated_amount_micros INTEGER CHECK(estimated_amount_micros>=0 AND estimated_amount_micros<=9000000000000000000),note TEXT NOT NULL,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),correction_projection_id TEXT UNIQUE REFERENCES correction_projection_versions(id),UNIQUE(order_id,id),FOREIGN KEY(order_id,previous_version_id) REFERENCES "purchase_order_versions"(order_id,id),FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id),CHECK((action IN('place','revise') AND status='open') OR (action='cancel' AND status='cancelled') OR(action='receive' AND status='received') OR (action='correct' AND status IN('open','received'))),CHECK((action='correct')=(correction_projection_id IS NOT NULL)));
CREATE TABLE "order_receipt_closures"(order_id TEXT NOT NULL REFERENCES purchase_orders(id),receipt_id TEXT PRIMARY KEY NOT NULL REFERENCES "receipts"(id),confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),initial_version_id TEXT NOT NULL,ordered_version_id TEXT NOT NULL,received_version_id TEXT NOT NULL UNIQUE,received_quantity TEXT NOT NULL,difference TEXT NOT NULL,FOREIGN KEY(order_id,initial_version_id) REFERENCES "purchase_order_versions"(order_id,id),FOREIGN KEY(order_id,ordered_version_id) REFERENCES "purchase_order_versions"(order_id,id),FOREIGN KEY(order_id,received_version_id) REFERENCES "purchase_order_versions"(order_id,id));
CREATE TABLE "purchase_order_heads"(order_id TEXT PRIMARY KEY NOT NULL REFERENCES purchase_orders(id),current_version_id TEXT NOT NULL,FOREIGN KEY(order_id,current_version_id) REFERENCES "purchase_order_versions"(order_id,id));
CREATE TABLE "receipts"(id TEXT PRIMARY KEY NOT NULL,confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,quantity_micros INTEGER NOT NULL CHECK(quantity_micros>0 AND quantity_micros<=9000000000000000),unit TEXT NOT NULL,input_quantity TEXT NOT NULL,input_unit TEXT NOT NULL,amount_micros INTEGER NOT NULL CHECK(amount_micros>=0 AND amount_micros<=9000000000000000000),receipt_date TEXT NOT NULL,note TEXT NOT NULL,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),source_kind TEXT NOT NULL,order_id TEXT REFERENCES purchase_orders(id),ordered_version_id TEXT,FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id),FOREIGN KEY(order_id,ordered_version_id) REFERENCES "purchase_order_versions"(order_id,id),CHECK((source_kind='direct' AND order_id IS NULL AND ordered_version_id IS NULL) OR (source_kind='order' AND order_id IS NOT NULL AND ordered_version_id IS NOT NULL)));
CREATE TABLE "receipt_reconciliations"(id TEXT PRIMARY KEY NOT NULL,receipt_id TEXT NOT NULL UNIQUE REFERENCES "receipts"(id),confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),result_json TEXT NOT NULL,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL UNIQUE REFERENCES snapshot_outbox(sequence));
CREATE TABLE "inclusion_links"(id TEXT PRIMARY KEY NOT NULL,reconciliation_id TEXT NOT NULL REFERENCES "receipt_reconciliations"(id),selection_position INTEGER NOT NULL CHECK(selection_position>=0 AND selection_position<20),portion_position INTEGER NOT NULL CHECK(portion_position>=0),row_json TEXT NOT NULL,UNIQUE(reconciliation_id,selection_position,portion_position));
CREATE TABLE purchase_returns(
        id TEXT PRIMARY KEY NOT NULL,confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),
        receipt_id TEXT NOT NULL REFERENCES receipts(id),receipt_version_id TEXT NOT NULL,
        material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,
        before_holding_version_id TEXT NOT NULL REFERENCES "holding_versions"(id),
        quantity_micros INTEGER NOT NULL CHECK(quantity_micros>0 AND quantity_micros<=9000000000000000),
        deducted_value_micros INTEGER NOT NULL CHECK(deducted_value_micros>=0 AND deducted_value_micros<=9000000000000000000),
        note TEXT NOT NULL,effect_json TEXT NOT NULL,recorded_at TEXT NOT NULL,
        sequence INTEGER NOT NULL UNIQUE REFERENCES snapshot_outbox(sequence),
        FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id));
CREATE TABLE "holding_versions"(purchase_return_id TEXT UNIQUE REFERENCES purchase_returns(id),id TEXT PRIMARY KEY NOT NULL,material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,previous_version_id TEXT,receipt_id TEXT UNIQUE REFERENCES "receipts"(id),baseline_receipt_id TEXT REFERENCES "receipts"(id),baseline_sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),quantity_micros INTEGER NOT NULL CHECK(quantity_micros>=0 AND quantity_micros<=9000000000000000),value_micros INTEGER NOT NULL CHECK(value_micros>=0 AND value_micros<=9000000000000000000),recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),production_effect_id TEXT UNIQUE,baseline_production_effect_id TEXT,observation_version_id TEXT UNIQUE REFERENCES "stocktake_versions"(id),baseline_observation_version_id TEXT REFERENCES "stocktake_versions"(id),waste_id TEXT UNIQUE REFERENCES "wastes"(id),reconciliation_effect_id TEXT UNIQUE,baseline_reconciliation_effect_id TEXT,correction_projection_id TEXT UNIQUE REFERENCES correction_projection_versions(id),baseline_correction_projection_id TEXT REFERENCES correction_projection_versions(id),last_valid_correction_price_id TEXT REFERENCES correction_price_bases(id),UNIQUE(material_id,id),FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id),FOREIGN KEY(material_id,previous_version_id) REFERENCES "holding_versions"(material_id,id),FOREIGN KEY(material_id,production_effect_id) REFERENCES production_effects(material_id,id),FOREIGN KEY(material_id,baseline_production_effect_id) REFERENCES production_effects(material_id,id),FOREIGN KEY(material_id,reconciliation_effect_id) REFERENCES "reconciliation_material_effects"(material_id,id),FOREIGN KEY(material_id,baseline_reconciliation_effect_id) REFERENCES "reconciliation_material_effects"(material_id,id),CHECK((receipt_id IS NOT NULL)+(production_effect_id IS NOT NULL)+(observation_version_id IS NOT NULL)+(waste_id IS NOT NULL)+(reconciliation_effect_id IS NOT NULL)+(correction_projection_id IS NOT NULL)+(purchase_return_id IS NOT NULL)=1),CHECK((baseline_receipt_id IS NOT NULL)+(baseline_production_effect_id IS NOT NULL)+(baseline_observation_version_id IS NOT NULL)+(baseline_reconciliation_effect_id IS NOT NULL)+(baseline_correction_projection_id IS NOT NULL)=1),CHECK(quantity_micros>0 OR value_micros=0));
CREATE TABLE "holding_heads"(material_id TEXT PRIMARY KEY NOT NULL REFERENCES materials(id),current_version_id TEXT,last_valid_version_id TEXT,unknown_correction_projection_id TEXT REFERENCES correction_projection_versions(id),last_valid_correction_price_id TEXT,FOREIGN KEY(material_id,current_version_id) REFERENCES "holding_versions"(material_id,id),FOREIGN KEY(material_id,last_valid_version_id) REFERENCES "holding_versions"(material_id,id),FOREIGN KEY(material_id,last_valid_correction_price_id) REFERENCES correction_price_bases(material_id,id),CHECK((current_version_id IS NOT NULL)+(unknown_correction_projection_id IS NOT NULL)=1),CHECK((last_valid_version_id IS NOT NULL)+(last_valid_correction_price_id IS NOT NULL)<=1),CHECK(current_version_id IS NOT NULL OR (last_valid_version_id IS NULL AND last_valid_correction_price_id IS NULL)));
CREATE TABLE "reconciliation_material_effects"(id TEXT PRIMARY KEY NOT NULL,reconciliation_id TEXT NOT NULL REFERENCES "receipt_reconciliations"(id),material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,before_holding_version_id TEXT REFERENCES "holding_versions"(id),row_json TEXT NOT NULL,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),UNIQUE(reconciliation_id,material_id),UNIQUE(material_id,id),FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id));
CREATE TABLE "sale_cost_rows"(sale_id TEXT NOT NULL REFERENCES sales(id),position INTEGER NOT NULL CHECK(position>=0 AND position<100),recipe_line_id TEXT NOT NULL REFERENCES recipe_lines(id),source_kind TEXT NOT NULL CHECK(source_kind IN('holding_average','last_valid','preregistered','missing')),holding_version_id TEXT REFERENCES "holding_versions"(id),material_price_id TEXT REFERENCES material_prices(id),price_amount_micros INTEGER CHECK(price_amount_micros>=0 AND price_amount_micros<=9000000000000000000),price_quantity_micros INTEGER CHECK(price_quantity_micros>0 AND price_quantity_micros<=9000000000000000),missing_reason TEXT,cost_micros INTEGER CHECK(cost_micros>=0 AND cost_micros<=9000000000000000000),correction_price_basis_id TEXT REFERENCES correction_price_bases(id),PRIMARY KEY(sale_id,position),UNIQUE(sale_id,recipe_line_id),CHECK((source_kind='missing' AND holding_version_id IS NULL AND material_price_id IS NULL AND price_amount_micros IS NULL AND price_quantity_micros IS NULL AND missing_reason IS NOT NULL)
        OR (source_kind='preregistered' AND holding_version_id IS NULL AND material_price_id IS NOT NULL AND price_amount_micros IS NOT NULL AND price_quantity_micros IS NOT NULL AND missing_reason IS NULL)
        OR (((source_kind='holding_average' AND holding_version_id IS NOT NULL AND correction_price_basis_id IS NULL) OR (source_kind='last_valid' AND ((holding_version_id IS NOT NULL)+(correction_price_basis_id IS NOT NULL)=1))) AND material_price_id IS NULL AND price_amount_micros IS NOT NULL AND price_quantity_micros IS NOT NULL AND missing_reason IS NULL)),CHECK(correction_price_basis_id IS NULL OR (source_kind='last_valid' AND holding_version_id IS NULL AND material_price_id IS NULL)));
CREATE TABLE "stocktake_versions"(id TEXT PRIMARY KEY NOT NULL,observation_id TEXT NOT NULL REFERENCES stocktake_observations(id),previous_version_id TEXT,previous_observation_version_id TEXT REFERENCES "stocktake_versions"(id),before_holding_version_id TEXT REFERENCES "holding_versions"(id),effect_json TEXT NOT NULL,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),correction_projection_id TEXT UNIQUE REFERENCES correction_projection_versions(id),logical_sequence INTEGER REFERENCES snapshot_outbox(sequence),observed_at TEXT,UNIQUE(observation_id,id),FOREIGN KEY(observation_id,previous_version_id) REFERENCES "stocktake_versions"(observation_id,id));
CREATE TABLE "wastes"(
        id TEXT PRIMARY KEY NOT NULL,
        confirmation_id TEXT NOT NULL UNIQUE REFERENCES business_confirmations(id),
        material_id TEXT NOT NULL,material_version_id TEXT NOT NULL,
        before_holding_version_id TEXT NOT NULL REFERENCES "holding_versions"(id),
        quantity_micros INTEGER NOT NULL CHECK(quantity_micros>0 AND quantity_micros<=9000000000000000),
        loss_value_micros INTEGER NOT NULL CHECK(loss_value_micros>=0 AND loss_value_micros<=9000000000000000000),
        reason TEXT NOT NULL CHECK(reason IN('discard','staff_meal')),note TEXT NOT NULL,
        effect_json TEXT NOT NULL,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL UNIQUE REFERENCES snapshot_outbox(sequence),
        FOREIGN KEY(material_id,material_version_id) REFERENCES material_versions(material_id,id));
CREATE TABLE "consumption_versions"(id TEXT PRIMARY KEY NOT NULL,observation_version_id TEXT NOT NULL REFERENCES "stocktake_versions"(id),previous_version_id TEXT REFERENCES "consumption_versions"(id),allocation_json TEXT NOT NULL,correction_projection_id TEXT UNIQUE REFERENCES correction_projection_versions(id),sequence INTEGER REFERENCES snapshot_outbox(sequence));
CREATE TABLE "inclusion_link_versions"(id TEXT PRIMARY KEY NOT NULL,link_id TEXT NOT NULL REFERENCES "inclusion_links"(id),previous_version_id TEXT,observation_version_id TEXT NOT NULL REFERENCES "stocktake_versions"(id),row_json TEXT NOT NULL,recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),UNIQUE(link_id,id),FOREIGN KEY(link_id,previous_version_id) REFERENCES "inclusion_link_versions"(link_id,id));
CREATE TABLE "inclusion_reservations"(id TEXT PRIMARY KEY NOT NULL,link_version_id TEXT NOT NULL UNIQUE REFERENCES "inclusion_link_versions"(id),row_json TEXT NOT NULL);
CREATE TABLE "stocktake_heads"(observation_id TEXT PRIMARY KEY NOT NULL REFERENCES stocktake_observations(id),current_version_id TEXT NOT NULL,FOREIGN KEY(observation_id,current_version_id) REFERENCES "stocktake_versions"(observation_id,id));
CREATE TABLE "consumption_heads"(observation_id TEXT PRIMARY KEY NOT NULL REFERENCES stocktake_observations(id),current_version_id TEXT NOT NULL UNIQUE REFERENCES "consumption_versions"(id));
CREATE TABLE "consumption_rows"(consumption_version_id TEXT NOT NULL REFERENCES "consumption_versions"(id),position INTEGER NOT NULL CHECK(position>=0),sale_id TEXT NOT NULL REFERENCES sales(id),sale_version_id TEXT NOT NULL,recipe_version_id TEXT NOT NULL REFERENCES recipe_versions(id),row_json TEXT NOT NULL,PRIMARY KEY(consumption_version_id,position),UNIQUE(consumption_version_id,sale_id),FOREIGN KEY(sale_id,sale_version_id) REFERENCES sale_versions(sale_id,id));
CREATE TABLE "inclusion_link_heads"(link_id TEXT PRIMARY KEY NOT NULL REFERENCES "inclusion_links"(id),current_version_id TEXT NOT NULL,FOREIGN KEY(link_id,current_version_id) REFERENCES "inclusion_link_versions"(link_id,id));
CREATE TABLE photo_assets(sha256 TEXT PRIMARY KEY,asset_key TEXT NOT NULL UNIQUE,format TEXT NOT NULL CHECK(format IN ('jpeg','png')),byte_length INTEGER NOT NULL CHECK(byte_length>0),width INTEGER NOT NULL CHECK(width>0),height INTEGER NOT NULL CHECK(height>0),recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence));
CREATE TABLE material_profile_versions(id TEXT PRIMARY KEY,material_id TEXT NOT NULL REFERENCES materials(id),material_version_id TEXT NOT NULL REFERENCES material_versions(id),previous_version_id TEXT REFERENCES material_profile_versions(id),copied_from_version_id TEXT REFERENCES material_profile_versions(id),recorded_at TEXT NOT NULL,sequence INTEGER NOT NULL REFERENCES snapshot_outbox(sequence),UNIQUE(material_id,sequence));
CREATE TABLE material_profile_heads(material_id TEXT PRIMARY KEY REFERENCES materials(id),current_version_id TEXT NOT NULL UNIQUE REFERENCES material_profile_versions(id));
CREATE TABLE material_profile_photos(profile_version_id TEXT NOT NULL REFERENCES material_profile_versions(id),id TEXT NOT NULL,position INTEGER NOT NULL CHECK(position>=0),asset_sha256 TEXT NOT NULL REFERENCES photo_assets(sha256),caption TEXT NOT NULL,is_primary INTEGER NOT NULL CHECK(is_primary IN (0,1)),PRIMARY KEY(profile_version_id,id),UNIQUE(profile_version_id,position));
CREATE TABLE material_profile_suppliers(profile_version_id TEXT NOT NULL REFERENCES material_profile_versions(id),position INTEGER NOT NULL CHECK(position>=0),url TEXT,description TEXT NOT NULL,PRIMARY KEY(profile_version_id,position));
CREATE INDEX material_versions_material ON material_versions(material_id,sequence);
CREATE INDEX material_prices_material ON material_prices(material_id,sequence);
CREATE INDEX business_revisions_record ON business_revisions(record_id,sequence);
CREATE INDEX recipe_versions_material ON recipe_versions(material_id,sequence);
CREATE INDEX recipe_lines_material ON recipe_lines(material_id,recipe_version_id);
CREATE INDEX production_effects_material ON production_effects(material_id,production_id);
CREATE INDEX sales_material ON sales(material_id);
CREATE INDEX sale_versions_sale ON sale_versions(sale_id);
CREATE INDEX purchase_order_versions_order ON purchase_order_versions(order_id,sequence);
CREATE INDEX receipts_material ON receipts(material_id,sequence);
CREATE INDEX purchase_returns_receipt ON purchase_returns(receipt_id);
CREATE INDEX purchase_returns_material ON purchase_returns(material_id);
CREATE INDEX holding_versions_material ON holding_versions(material_id,sequence);
CREATE INDEX wastes_material ON wastes(material_id);
CREATE INDEX consumption_rows_sale ON consumption_rows(sale_id);
